import pandas as pd

df = pd.DataFrame({
    "city": ["北京", "上海", "杭州", "成都"],
    "price": [120, 90, 150, 80],
})
sub = df[df["price"] > 85]
print("筛选后索引:", sub.index.tolist())

print("iloc[0] 永远是第一行:", sub.iloc[0].to_dict())
print("loc[0] 是标签 0 的那一行:", sub.loc[0].to_dict())

try:
    sub.loc[1]
except KeyError as e:
    print("loc[1] 报错:", str(e)[:50])

